export const isPullRequestAsk = (ask       ) =>
  Boolean(ask.subject?.pr) || Boolean(ask.subject?.repo);

/** What a pull request ask approves, as `owner/name #382 · 9d7e545`. */
export function pullRequestSubject(ask       )                     {
  const { repo, pr, head_sha: head } = ask.subject ?? {};
  if (!repo && pr === undefined) return undefined;
  return [
    [repo?.split("/").slice(-2).join("/"), pr === undefined ? undefined : `#${pr}`]
      .filter(Boolean)
      .join(" "),
    head?.slice(0, 7),
  ]
    .filter(Boolean)
    .join(" · ");
}

