/** The headline a person reads first: the card's title, else its question, else the body. */
export function askHeadline(ask       )         {
  return ask.card?.title ?? ask.card?.question ?? ask.body?.split("\n")[0] ?? "A decision";
}

const deadlineFormats = new Map                             ();

/** `Fri 3:04 PM PST` in `timeZone` (the reader's own when absent). */
function deadlineTime(at        , timeZone                    )         {
  const time = Date.parse(at);
  if (Number.isNaN(time)) return at;
  const key = timeZone ?? "";
  let format = deadlineFormats.get(key);
  if (!format) {
    format = new Intl.DateTimeFormat("en-US", {
      weekday: "short",
      hour: "numeric",
      minute: "2-digit",
      timeZoneName: "short",
      ...(timeZone ? { timeZone } : {}),
    });
    deadlineFormats.set(key, format);
  }
  return format.format(time).replace(",", "");
}

/**
 * What a card that applies its recommendation at its deadline says (zm SPEC 16 "Defaults with
 * deadlines"): before, what happens when; after, that it happened, which an owner can undo or
 * keep (keeping is answering with `recommend`); once undone, that it waits for a real answer.
 * Nothing for an answered ask or one without a default.
 */
export function askDefault(
  ask       ,
  timeZone         ,
)

              {
  const recommend = ask.card?.recommend;
  const label = ask.card?.choices.find((choice) => choice.key === recommend)?.label;
  if (!ask.apply_default || !ask.by || !recommend || !label) return undefined;
  if (ask.status !== "open" || ask.decision) return undefined;
  if (ask.default_undone) {
    return { kind: "undone", line: "Default undone; waiting for your answer." };
  }
  if (ask.default_applied) {
    return {
      kind: "applied",
      line: `Done by default at ${deadlineTime(ask.default_applied, timeZone)}: ${label}. Nobody answered in time.`,
      recommend,
    };
  }
  return {
    kind: "pending",
    line: `I will do ${label} at ${deadlineTime(ask.by, timeZone)} unless you say no.`,
  };
}

