const ABBREVIATION = /\b(?:e\.g|i\.e|etc|vs|approx|Dr|Mr|Ms|Mrs|St)\.\)?$/i;

/**
 * An agent's `AGENT DECISION: <what it chose and why>` as a card reads it: the first sentence is
 * the choice, the rest is why.
 */
export function agentDecisionParts(text        )

  {
  const body = text.replace(/^AGENT DECISION:?\s*/i, "").trim();
  for (const end of body.matchAll(/[.!?]\)?\s+(?=[A-Z0-9"'(])/g)) {
    const before = body.slice(0, end.index + end[0].trimEnd().length);
    if (ABBREVIATION.test(before)) continue;
    return { choice: before, why: body.slice(end.index + end[0].length).trim() || undefined };
  }
  return { choice: body, why: undefined };
}

// zm's labels that put a work item in a person's inbox (zm internal/approvals/inbox.go).
const STEP_LABELS = ["owner-run", "human"];
const DECISION_LABELS = ["owner-decision", "decision", "questions", "needs-night-ruling"];

/**
 * What a person does with a work item waiting on them, which has no ask: a step only they can
 * run (done closes it), or a decision nobody wrote options for (they write it). `handBack` is
 * every label that put it in their inbox: removing them gives it back to agents.
 */
export function workAction(
  work                                                         ,
  reader                       ,
)                                                                                 {
  const labels = work.labels ?? [];
  const named = (label        ) =>
    reader.some((name) => [`owner:${name}`, `ask:${name}`, `needs-${name}`].includes(label)) ||
    label === "ask:owner";
  const handBack = labels.filter(
    (label) => STEP_LABELS.includes(label) || DECISION_LABELS.includes(label) || named(label),
  );
  const decision =
    !labels.some((label) => STEP_LABELS.includes(label)) &&
    labels.some((label) => DECISION_LABELS.includes(label));
  return { kind: decision ? "decide" : "step", handBack };
}
